draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // laughing
  ctx.beginPath();
  ctx.arc(W/2 - 10, H/2 - 10, 5, 0, Math.PI, false);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 10, H/2 - 10, 5, 0, Math.PI, false);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 15, H/2);
  ctx.lineTo(W/2 + 15, H/2);
  ctx.stroke();

  // absurdism symbol (a circle with an arrow pointing to itself)
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 70, H/2);
  ctx.lineTo(W/2 + 50, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 60, H/2 - 5);
  ctx.lineTo(W/2 + 60, H/2 + 5);
  ctx.stroke();

  // meaningless loop
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 + Math.sin(t) * 50, H/2 + 100 + Math.cos(t) * 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 100 + Math.cos(t) * 50);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();

  ctx.restore();
}
